/* Moss — warm, tactile, optimistic, a little odd */

:root {
  --paper: #f7f0e2;
  --paper-2: #efe4cd;
  --card: #fffdf7;
  --ink: #35312a;
  --ink-soft: #6f6655;
  --ink-faint: #9c917c;

  --moss: #5f7d4a;
  --moss-deep: #47603a;
  --moss-soft: #8ab468;
  --clay: #c9744f;
  --clay-deep: #a85736;
  --ochre: #d7a13f;
  --ochre-deep: #9a7224;

  --line: #e3d8c1;
  --line-strong: #cfc2a5;

  --tint-fern: #e7eedb;
  --tint-pothos: #f4e9cd;
  --tint-cactus: #f6e3d5;
  --tint-calathea: #ece4dc;

  --radius: 26px;
  --shadow: 0 10px 24px -14px rgba(76, 61, 38, 0.35);
  --focus: #c9744f;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  color: var(--ink);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background-color: var(--paper);
  background-image:
    radial-gradient(38rem 26rem at 110% -6%, rgba(201, 116, 79, 0.10), transparent 60%),
    radial-gradient(30rem 24rem at -12% 18%, rgba(95, 125, 74, 0.12), transparent 62%),
    radial-gradient(24rem 20rem at 90% 100%, rgba(215, 161, 63, 0.10), transparent 60%);
  background-attachment: fixed;
  -webkit-font-smoothing: antialiased;
}

.shell {
  width: min(1080px, 100% - 2rem);
  margin-inline: auto;
  padding-block: 1.25rem 4rem;
}

/* ---------- Header ---------- */

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding-block: 0.5rem 1.5rem;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  text-decoration: none;
  color: var(--ink);
  border-radius: 12px;
}

.brand-mark {
  width: 2.2rem;
  height: 2.2rem;
}

.brand-mark .stem {
  fill: none;
  stroke: var(--moss-deep);
  stroke-width: 2.4;
  stroke-linecap: round;
}

.brand-mark .leaf-a {
  fill: var(--moss);
}

.brand-mark .leaf-b {
  fill: var(--moss-soft);
}

.brand-word {
  font-family: "Iowan Old Style", "Palatino Linotype", Georgia, serif;
  font-size: 1.6rem;
  font-weight: 700;
  letter-spacing: 0.01em;
}

.today {
  margin: 0;
  color: var(--ink-soft);
  font-size: 0.95rem;
}

/* ---------- Layout ---------- */

.layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
  align-items: start;
}

.section-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 0.75rem;
}

.section-head h2 {
  margin: 0;
  font-family: "Iowan Old Style", "Palatino Linotype", Georgia, serif;
  font-size: 1.45rem;
  letter-spacing: 0.005em;
}

.count {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--clay-deep);
  background: #f4e3d4;
  padding: 0.25rem 0.7rem;
  border-radius: 999px;
  white-space: nowrap;
}

/* ---------- Plant list ---------- */

.plant-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.9rem;
}

.plant {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  overflow: hidden;
  transition: transform 0.25s ease, opacity 0.3s ease, box-shadow 0.25s ease;
}

.plant:hover {
  transform: translateY(-2px);
  box-shadow: 0 14px 30px -16px rgba(76, 61, 38, 0.42);
}

.plant.leaving {
  opacity: 0;
  transform: translateY(-10px) scale(0.96);
}

/* expandable row */
.expand {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 0.85rem;
  width: 100%;
  padding: 0.9rem 1rem;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.leaf-tile {
  --tint: var(--moss-soft);
  width: 3.6rem;
  height: 3.6rem;
  border-radius: 46% 54% 52% 48% / 55% 48% 52% 45%;
  background: var(--tint);
  display: grid;
  place-items: center;
  flex: none;
}

.leaf-tile svg {
  width: 2.7rem;
  height: 2.7rem;
  display: block;
}

.meta {
  min-width: 0;
}

.name {
  display: block;
  font-weight: 700;
  font-size: 1.05rem;
  letter-spacing: 0.002em;
}

.sub {
  display: block;
  color: var(--ink-soft);
  font-size: 0.85rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.task-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.4rem;
  margin-top: 0.35rem;
}

.task-chip {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--moss-deep);
  background: #eef1e6;
  border-radius: 999px;
  padding: 0.1rem 0.55rem;
}

.due {
  font-size: 0.78rem;
  font-weight: 700;
  border-radius: 999px;
  padding: 0.1rem 0.55rem;
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
}

.due::before {
  content: "";
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 50%;
  background: currentColor;
  flex: none;
}

.due.overdue {
  color: var(--clay-deep);
  background: #f7e0d3;
}

.due.today {
  color: var(--ochre-deep);
  background: #f7ead0;
}

.due.tomorrow {
  color: var(--ink-soft);
  background: #ece6d6;
}

.chevron {
  width: 1.2rem;
  height: 1.2rem;
  color: var(--ink-faint);
  transition: transform 0.25s ease;
  flex: none;
}

.expand[aria-expanded="true"] .chevron {
  transform: rotate(180deg);
}

/* action bar */
.actions {
  display: flex;
  gap: 0.6rem;
  padding: 0 1rem 1rem;
}

.btn {
  font: inherit;
  font-weight: 600;
  border-radius: 14px;
  padding: 0.55rem 1rem;
  cursor: pointer;
  border: 1.5px solid transparent;
  transition: transform 0.15s ease, background 0.2s ease, border-color 0.2s ease;
  -webkit-tap-highlight-color: transparent;
}

.btn:active {
  transform: scale(0.97);
}

.btn.primary {
  background: var(--moss);
  color: #fdfbf5;
  flex: 1;
}

.btn.primary:hover {
  background: var(--moss-deep);
}

.btn.ghost {
  background: transparent;
  color: var(--ink-soft);
  border-color: var(--line-strong);
}

.btn.ghost:hover {
  border-color: var(--clay);
  color: var(--clay-deep);
}

.btn.text {
  display: inline-flex;
  color: var(--moss-deep);
  text-decoration: underline;
  text-underline-offset: 3px;
  padding: 0.5rem 0.25rem;
}

/* ---------- Detail panel ---------- */

.detail {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 0.3s ease;
}

.detail.open {
  grid-template-rows: 1fr;
}

.detail-inner {
  overflow: hidden;
}

.detail-body {
  padding: 0 1rem 1rem;
  border-top: 1px dashed var(--line-strong);
  margin: 0 1rem;
}

.facts {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.6rem;
  padding: 1rem 0;
}

.fact {
  background: var(--paper);
  border-radius: 14px;
  padding: 0.6rem 0.7rem;
}

.fact-label {
  display: block;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--ink-faint);
  font-weight: 700;
}

.fact-value {
  display: block;
  font-size: 0.9rem;
  font-weight: 600;
  margin-top: 0.1rem;
}

.log-title {
  margin: 0.25rem 0 0.5rem;
  font-size: 0.85rem;
  color: var(--ink-soft);
}

.history {
  list-style: none;
  margin: 0;
  padding: 0;
}

.history li {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.45rem 0;
  font-size: 0.9rem;
  border-bottom: 1px solid var(--paper-2);
}

.history li:last-child {
  border-bottom: 0;
}

.history .h-date {
  color: var(--ink-faint);
  font-size: 0.8rem;
  min-width: 4.4rem;
}

.history svg {
  width: 1.05rem;
  height: 1.05rem;
  color: var(--moss);
  flex: none;
}

.history svg.obs {
  color: var(--clay);
}

/* ---------- Weekly rhythm ---------- */

.rhythm {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 1.1rem 1.1rem 1.25rem;
}

.rhythm-hint {
  margin: -0.4rem 0 1rem;
  color: var(--ink-soft);
  font-size: 0.85rem;
}

.rhythm-chart {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 0.5rem;
  height: 8.5rem;
  padding-top: 0.75rem;
}

.day {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.45rem;
  height: 100%;
  justify-content: flex-end;
}

.bar-track {
  position: relative;
  width: 100%;
  max-width: 2.1rem;
  height: 100%;
  border-radius: 999px;
  background: var(--paper-2);
  overflow: hidden;
  display: flex;
  align-items: flex-end;
}

.bar-fill {
  width: 100%;
  border-radius: 999px;
  background: linear-gradient(var(--moss-soft), var(--moss));
  transform-origin: bottom;
  animation: rise 0.7s cubic-bezier(0.2, 0.7, 0.3, 1) both;
}

.bar-leaf {
  position: absolute;
  left: 50%;
  transform: translate(-50%, 0);
  width: 0.8rem;
  height: 0.8rem;
  border-radius: 50% 50% 50% 0;
  background: var(--moss-deep);
  rotate: -45deg;
}

.dow {
  font-size: 0.7rem;
  color: var(--ink-faint);
  font-weight: 600;
  letter-spacing: 0.02em;
}

@keyframes rise {
  from { transform: scaleY(0); }
  to { transform: scaleY(1); }
}

/* ---------- Gentle note ---------- */

.gentle {
  margin-top: 1.5rem;
  text-align: center;
  padding: 1rem 1.5rem;
}

.gentle-text {
  margin: 0;
  font-family: "Iowan Old Style", "Palatino Linotype", Georgia, serif;
  font-size: 1.05rem;
  color: var(--ink-soft);
  font-style: italic;
}

.gentle-attr {
  margin: 0.35rem 0 0;
  font-size: 0.78rem;
  color: var(--ink-faint);
}

/* ---------- All done ---------- */

.all-done {
  text-align: center;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 2.5rem 1.5rem;
}

.all-done-art {
  width: 8.5rem;
  height: 7rem;
  margin-inline: auto;
}

.all-done-art .pot {
  fill: #dca37a;
}

.all-done-art .sprout {
  fill: none;
  stroke: var(--moss-deep);
  stroke-width: 3;
  stroke-linecap: round;
}

.all-done-art .leaf-l,
.all-done-art .leaf-r,
.all-done-art .leaf-l2 {
  fill: var(--moss);
  transform-box: fill-box;
  transform-origin: center;
  animation: sway 2.6s ease-in-out infinite;
}

.all-done-art .leaf-r {
  fill: var(--moss-soft);
  animation-delay: 0.4s;
}

.all-done-art .leaf-l2 {
  animation-delay: 0.8s;
}

.all-done-art .spark {
  fill: var(--ochre);
  animation: blink 1.8s ease-in-out infinite;
}

.all-done-art .s2 { animation-delay: 0.4s; }
.all-done-art .s3 { animation-delay: 0.8s; }

@keyframes sway {
  0%, 100% { transform: rotate(-4deg); }
  50% { transform: rotate(4deg); }
}

@keyframes blink {
  0%, 100% { opacity: 0.35; transform: scale(0.85); }
  50% { opacity: 1; transform: scale(1.15); }
}

.all-done h3 {
  margin: 1rem 0 0.25rem;
  font-family: "Iowan Old Style", "Palatino Linotype", Georgia, serif;
  font-size: 1.5rem;
}

.all-done-sub {
  margin: 0;
  color: var(--ink-soft);
}

.done-list {
  list-style: none;
  margin: 1.25rem auto 1.5rem;
  padding: 0;
  max-width: 20rem;
  display: grid;
  gap: 0.5rem;
  text-align: left;
}

.done-list li {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.55rem 0.8rem;
  background: var(--paper);
  border-radius: 14px;
  font-weight: 600;
}

.done-list .tick {
  width: 1.15rem;
  height: 1.15rem;
  border-radius: 50%;
  background: var(--moss);
  color: #fff;
  display: inline-grid;
  place-items: center;
  font-size: 0.7rem;
  flex: none;
}

/* ---------- Toast ---------- */

.toast {
  position: fixed;
  left: 50%;
  bottom: 1.25rem;
  transform: translateX(-50%) translateY(0);
  display: flex;
  align-items: center;
  gap: 1rem;
  background: var(--ink);
  color: #fbf7ee;
  padding: 0.75rem 0.9rem 0.75rem 1.1rem;
  border-radius: 16px;
  box-shadow: 0 16px 34px -14px rgba(0, 0, 0, 0.5);
  max-width: min(92vw, 30rem);
  z-index: 50;
}

.toast[hidden] {
  display: none;
}

.toast.show {
  animation: toast-in 0.28s cubic-bezier(0.2, 0.7, 0.3, 1) both;
}

@keyframes toast-in {
  from { opacity: 0; transform: translateX(-50%) translateY(1rem); }
  to { opacity: 1; transform: translateX(-50%) translateY(0); }
}

.toast-msg {
  font-size: 0.92rem;
  line-height: 1.35;
}

.toast-undo {
  font: inherit;
  font-weight: 700;
  color: #ffe0c8;
  background: transparent;
  border: 0;
  padding: 0.35rem 0.5rem;
  border-radius: 8px;
  cursor: pointer;
  white-space: nowrap;
}

.toast-undo:hover {
  color: #fff;
  text-decoration: underline;
}

/* ---------- Focus ---------- */

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 8px;
}

/* ---------- Utility ---------- */

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

/* ---------- Reduced motion ---------- */

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }
}

/* ---------- Desktop ---------- */

@media (min-width: 860px) {
  .shell {
    padding-top: 1.75rem;
  }

  .layout {
    grid-template-columns: minmax(0, 1fr) 20rem;
    gap: 2rem;
  }

  .plant-list {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .side {
    position: sticky;
    top: 1.5rem;
  }

  .gentle {
    margin-top: 1.5rem;
  }
}

@media (min-width: 1120px) {
  .layout {
    grid-template-columns: minmax(0, 1fr) 21rem;
  }
}

